var builder = WebApplication.CreateBuilder(args);
builder.Services.AddHttpClient<RatesClient>();
builder.Services.AddScoped<PriceCalculator>();
var app = builder.Build();

app.MapGet("/quote", (decimal amount, string currency, PriceCalculator calc) =>
    calc.ToLocal(amount, currency));
app.Run();

public sealed class PriceCalculator(RatesClient rates)
{
    public decimal ToLocal(decimal amount, string currency)
    {
        // No deadlock, but this pool thread is parked until the call returns
        var rate = rates.GetRateAsync(currency).GetAwaiter().GetResult();
        return amount * rate;
    }
}

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddHttpClient<RatesClient>();
builder.Services.AddScoped<PriceCalculator>();
var app = builder.Build();

app.MapGet("/quote", (decimal amount, string currency, PriceCalculator calc,
    CancellationToken ct) => calc.ToLocalAsync(amount, currency, ct));
app.Run();

public sealed class PriceCalculator(RatesClient rates)
{
    public async Task<decimal> ToLocalAsync(decimal amount, string currency,
        CancellationToken ct)
    {
        // The thread goes back to the pool while the HTTP call is in flight
        var rate = await rates.GetRateAsync(currency, ct);
        return amount * rate;
    }
}
